/*
 * A290886  Let S be the sequence generated by these rules: 0 is in S, and if
 *          z is in S, then z * (1+i) and (z-1) * (1+i) + 1 are in S (where i
 *          denotes the imaginary unit), and duplicates are deleted as they
 *          occur; a(n) = the square of the norm of the n-th term of S.
 * https://oeis.org/A290886
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, look
 * Formula:   a(n) computed by BFS expanding the set S of Gaussian integers
 *            generated from 0 with the transformations: f(z) = z * (1+i) ->
 *            (a-b, a+b) g(z) = (z-1)*(1+i)+1 -> (a-b, a+b-1) duplicates are
 *            discarded as they appear. a(n) = |z_n|^2 = a_n^2 + b_n^2
 * Range:     u8 n <= 192, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* NOTE: The implementation relies only on integer operations and a
   simple hash table for duplicate detection.  It works for any
   unsigned integer type seq_t and idx_t = uint64_t provided by the
   surrounding environment. */

#include <stdlib.h>
#include <stdint.h>
#include <stddef.h>

/* ----- Small linear‑probe hash table for (int64_t,int64_t) pairs ----- */
#define HT_BITS     15
#define HT_SIZE     (1U << HT_BITS)

typedef struct {
    int64_t a;
    int64_t b;
    uint8_t used;      /* 0 = empty, 1 = occupied */
} ht_entry;

static ht_entry hash_table[HT_SIZE];
static int hash_inited = 0;

static inline size_t ht_hash(int64_t a, int64_t b)
{
    /* Good enough hash for signed values; cast to unsigned to mix signs */
    return (((size_t)(uint64_t)a * 2654435761U) ^ (size_t)(uint64_t)b) & (HT_SIZE - 1);
}

static int ht_find(int64_t a, int64_t b)
{
    size_t h = ht_hash(a, b);
    while (hash_table[h].used) {
        if (hash_table[h].a == a && hash_table[h].b == b)
            return 1;
        h = (h + 1) & (HT_SIZE - 1);
    }
    return 0;
}

static void ht_insert(int64_t a, int64_t b)
{
    size_t h = ht_hash(a, b);
    while (hash_table[h].used)
        h = (h + 1) & (HT_SIZE - 1);
    hash_table[h].used = 1;
    hash_table[h].a = a;
    hash_table[h].b = b;
}

/* ----- Dynamic arrays for real and imaginary parts ----- */
static int64_t *real_arr = NULL;
static int64_t *imag_arr = NULL;
static size_t array_capacity = 0;            /* allocated slots (size_t) */
static size_t array_size    = 0;             /* number of unique terms */
static size_t front_index   = 0;             /* index of next term to expand */

/* ----- Main routine ----- */
seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* safety, not used in tests */

    /* Initialise on first call */
    if (!hash_inited) {
        hash_inited = 1;
        array_capacity = (size_t) ((n > 64) ? n : 64);
        real_arr = (int64_t*)malloc(array_capacity * sizeof(int64_t));
        imag_arr = (int64_t*)malloc(array_capacity * sizeof(int64_t));
        array_size = 1;             /* 0 is first term */
        front_index = 0;
        for (size_t i = 0; i < HT_SIZE; ++i) hash_table[i].used = 0;
        ht_insert(0, 0);
        real_arr[0] = 0;
        imag_arr[0] = 0;
    }

    /* Grow arrays if caller requests more than current capacity */
    if ((size_t)n > array_capacity) {
        size_t new_cap = (size_t) ((size_t)n + 64);
        real_arr = (int64_t*)realloc(real_arr, new_cap * sizeof(int64_t));
        imag_arr = (int64_t*)realloc(imag_arr, new_cap * sizeof(int64_t));
        array_capacity = new_cap;
    }

    /* Generate terms until we have at least n distinct ones */
    while (array_size < n) {
        int64_t a_cur = real_arr[front_index];
        int64_t b_cur = imag_arr[front_index];
        ++front_index;

        /* f(z) = z * (1+i)  -> (a - b, a + b) */
        int64_t a_f = a_cur - b_cur;
        int64_t b_f = a_cur + b_cur;
        if (!ht_find(a_f, b_f)) {
            ht_insert(a_f, b_f);
            real_arr[array_size] = a_f;
            imag_arr[array_size] = b_f;
            ++array_size;
        }

        /* g(z) = (z-1)*(1+i)+1  -> (a - b, a + b - 1) */
        int64_t a_g = a_cur - b_cur;
        int64_t b_g = a_cur + b_cur - 1;
        if (!ht_find(a_g, b_g)) {
            ht_insert(a_g, b_g);
            real_arr[array_size] = a_g;
            imag_arr[array_size] = b_g;
            ++array_size;
        }
    }

    /* Retrieve nth term (1‑based) */
    int64_t a_n = real_arr[n - 1];
    int64_t b_n = imag_arr[n - 1];

    /* Compute |z|^2 = a^2 + b^2 using seq_t */
    seq_t abs_a = (a_n >= 0) ? (seq_t)a_n : (seq_t)(-a_n);
    seq_t abs_b = (b_n >= 0) ? (seq_t)b_n : (seq_t)(-b_n);

    return abs_a * abs_a + abs_b * abs_b;
}
